"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["96893"],{46116(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.localidade_ausente","status":422,"titulo":"Localidade que rege a contagem dos prazos n\xe3o declarada"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.localidade_ausente","requisitos":["UNI-REQ-0111"],"oQueAconteceu":["A opera\xe7\xe3o foi recusada porque a **localidade** n\xe3o foi declarada \u2014 o munic\xedpio\\ncujo calend\xe1rio rege a contagem dos prazos do certame. A recusa acontece na cria\xe7\xe3o do processo, na defini\xe7\xe3o da localidade e em cada transi\xe7\xe3o que gera vers\xe3o publicada; o campo `detail` da resposta diz qual delas foi recusada.","A localidade determina quais feriados estaduais e municipais incidem sobre os\\nprazos de recurso. Ela varia de um certame para outro: a institui\xe7\xe3o pode\\npublicar processo cujo calend\xe1rio \xe9 o de outro munic\xedpio. Por isso o servidor n\xe3o\\na atribui por omiss\xe3o nem a deduz da unidade administradora, do campus de oferta\\nou da sede \u2014 deduzir devolveria a rigidez que a tornou configur\xe1vel. O campo que\\na interface apresenta preenchido \xe9 sugest\xe3o, n\xe3o valor atribu\xeddo: enquanto n\xe3o\\nenviado, nada foi declarado. Ter cidade\\ncadastrada na unidade administradora n\xe3o dispensa a declara\xe7\xe3o: o servidor n\xe3o\\nusa aquela cidade para completar esta.","Nenhum processo existe sem ela, nem em rascunho. O cadastro nasce junto com o\\nedital de abertura, e \xe9 nele que a localidade regente est\xe1 declarada \u2014 por isso\\na exig\xeancia come\xe7a na cria\xe7\xe3o, e n\xe3o na v\xe9spera de publicar. Como a vers\xe3o\\npublicada \xe9 imut\xe1vel, a informa\xe7\xe3o precisa estar l\xe1 desde o come\xe7o: n\xe3o h\xe1 como\\ncomplet\xe1-la depois.","Depois da cria\xe7\xe3o, a recusa vale nas duas transi\xe7\xf5es que geram vers\xe3o, e n\xe3o s\xf3 na tela de publica\xe7\xe3o \u2014 validar num caminho s\xf3 deixaria o outro aberto.\\nComo a localidade \xe9 exigida desde a cria\xe7\xe3o e n\xe3o pode ser removida, chegar a\\numa dessas transi\xe7\xf5es sem ela n\xe3o \xe9 estado alcan\xe7\xe1vel pelo fluxo normal: a\\nrecusa est\xe1 ali para defender a invariante de qualquer caminho de escrita que\\nvenha a contorn\xe1-la."],"comoResolver":["Declare a localidade na configura\xe7\xe3o do processo, com o trio j\xe1 can\xf4nico no\\nsistema:","- **c\xf3digo IBGE** de sete d\xedgitos, com prefixo coerente com a UF informada;\\n- **nome** do munic\xedpio, n\xe3o vazio;\\n- **UF**.","O c\xf3digo IBGE \xe9 o \xfanico valor normativo \u2014 \xe9 dele que se derivam o munic\xedpio e a\\nunidade federativa cujos feriados incidem. Nome e UF persistidos s\xe3o cache de\\nexibi\xe7\xe3o: se divergirem, o r\xf3tulo sai errado, nunca o prazo.","Na cria\xe7\xe3o, informe a localidade junto com os demais dados do cadastro inicial.\\nSe a interface apresentar o campo j\xe1 preenchido com a cidade da unidade\\nadministradora, confirme-a ou troque pelo munic\xedpio que o edital declara \u2014 o\\nvalor sugerido s\xf3 vale como declara\xe7\xe3o depois de enviado.","O campo continua edit\xe1vel enquanto o processo est\xe1 em rascunho. Declarada a localidade, repita a\\nopera\xe7\xe3o."],"ondeAparece":["Cria\xe7\xe3o do processo seletivo","Defini\xe7\xe3o da localidade do processo seletivo","Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"0258f07cac6c9b7f9d70290a4b0385549eb99572"}}')}}]);